class Solution {
public:
    int maximumCandies(vector<int>& candies, long long k) {
        long long total = 0;
        int maxC = 0;
        for (int c : candies) {
            total += c;
            if (c > maxC) maxC = c;
        }
        if (total < k) return 0;
        int lo = 1, hi = maxC, ans = 0;
        while (lo <= hi) {
            int mid = lo + (hi - lo) / 2;
            long long count = 0;
            for (int c : candies) {
                count += c / mid;
            }
            if (count >= k) {
                ans = mid;
                lo = mid + 1;
            } else {
                hi = mid - 1;
            }
        }
        return ans;
    }
};
